#!/usr/bin/env python3# -*- coding: utf-8 -*-`n`nimport argparse`nimport os`nimport json`nimport subprocess`nfrom datetime import datetime`n`nCONFIG_DIR = os.path.expanduser("~/.gitup")`nCONFIG_FILE = os.path.join(CONFIG_DIR, "config.json")`n`nclass GitUploader:`n    def __init__(self):`n        self.config = {}`n        self.current_repo = None`n        self.load_config()`n    `n    def load_config(self):`n        if os.path.exists(CONFIG_FILE):`n            try:`n                with open(CONFIG_FILE, "r", encoding="utf-8") as f:`n                    self.config = json.load(f)`n            except:`n                self.config = {"repositories": {}}`n        else:`n            self.config = {"repositories": {}}`n        self.current_repo = self.config.get("current_repo")`n    `n    def save_config(self):`n        self.config["current_repo"] = self.current_repo`n        with open(CONFIG_FILE, "w", encoding="utf-8") as f:`n            json.dump(self.config, f, indent=2)`n    `n    def repo_create(self, name):`n        if name in self.config.get("repositories", {}):`n            print(f"仓库 {name} 已存在")`n            return`n        self.config.setdefault("repositories", {})[name] = {"templates": {}}`n        self.save_config()`n        print(f"创建仓库: {name}")`n    `n    def repo_list(self):`n        repos = self.config.get("repositories", {})`n        if not repos:`n            print("没有仓库")`n            return`n        print("仓库列表:")`n        for name in repos:`n            current = " [当前]" if name == self.current_repo else ""`n            print(f"  - {name}{current}")`n    `n    def repo_enter(self, name):`n        if name not in self.config.get("repositories", {}):`n            print(f"仓库 {name} 不存在")`n            return`n        self.current_repo = name`n        self.save_config()`n        print(f"进入仓库: {name}")`n    `n    def template_add(self, name, template, command):`n        repos = self.config.get("repositories", {})`n        if name not in repos:`n            print(f"仓库 {name} 不存在")`n            return`n        if template in repos[name].get("templates", {}):`n            print(f"模板 {template} 已存在")`n            return`n        repos[name].setdefault("templates", {})[template] = command`n        self.save_config()`n        print(f"添加模板: {template}")`n    `n    def template_list(self, name):`n        repos = self.config.get("repositories", {})`n        if name not in repos:`n            print(f"仓库 {name} 不存在")`n            return`n        templates = repos[name].get("templates", {})`n        if not templates:`n            print(f"仓库 {name} 没有模板")`n            return`n        print(f"仓库 {name} 模板:")`n        for t in templates:`n            print(f"  - {t}: {templates[t]}")`n    `n    def generate_command(self, name, template):`n        repos = self.config.get("repositories", {})`n        if name not in repos:`n            print(f"仓库 {name} 不存在")`n            return`n        templates = repos[name].get("templates", {})`n        if template not in templates:`n            print(f"模板 {template} 不存在")`n            return`n        `n        cmd = templates[template]`n        # 替换占位符`n        cmd = cmd.replace("%Y", datetime.now().strftime("%Y"))`n        cmd = cmd.replace("%m", datetime.now().strftime("%m"))`n        cmd = cmd.replace("%d", datetime.now().strftime("%d"))`n        cmd = cmd.replace("%H", datetime.now().strftime("%H"))`n        cmd = cmd.replace("%M", datetime.now().strftime("%M"))`n        cmd = cmd.replace("%S", datetime.now().strftime("%S"))`n        `n        print(f"生成的命令:\n{cmd}")`n        print("执行? (y/N): ", end="")`n        if input().lower() == "y":`n            try:`n                subprocess.run(cmd, shell=True)`n                print("执行完成")`n            except Exception as e:`n                print(f"执行错误: {e}")`n`ndef main():`n    parser = argparse.ArgumentParser(description="GitUploader")`n    parser.add_argument("command", choices=["repo", "template", "run"])`n    parser.add_argument("subcommand", help="子命令")`n    parser.add_argument("name", help="名称")`n    parser.add_argument("template", help="模板名称")`n    parser.add_argument("command_str", help="命令字符串")`n    args = parser.parse_args()`n    `n    gitup = GitUploader()`n    `n    if args.command == "repo":`n        if args.subcommand == "create":`n            gitup.repo_create(args.name)`n        elif args.subcommand == "list":`n            gitup.repo_list()`n        elif args.subcommand == "enter":`n            gitup.repo_enter(args.name)`n    elif args.command == "template":`n        if args.subcommand == "add":`n            gitup.template_add(args.name, args.template, args.command_str)`n        elif args.subcommand == "list":`n            gitup.template_list(args.name)`n    elif args.command == "run":`n        gitup.generate_command(args.name, args.template)`n`nif __name__ == "__main__":`n    main()
